<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth';import {errorText} from '../api';const email=ref(''),password=ref(''),error=ref(''),busy=ref(false);const router=useRouter();async function submit(){busy.value=true;error.value='';try{await useAuth().login(email.value,password.value);await router.push('/')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
